\begin{defn}[Membership oracle]\label{def:membership-oracle}
    We are given a convex body $\mc K$ which has $B_1(0) \subseteq \mc K \subseteq B_D(0) \subset \R^d$ for some $D > 0$. We assume access to a \emph{membership oracle}, which, given a point $x \in \R^d$, answers \emph{Yes} or \emph{No} to the query ``Is $x \in \mc K$?''
\end{defn}

\begin{defn}[Distance and divergence] \label{def:p-dist}
    Let $\mu, \nu$ be two probability measures on $\R^d$. Their \emph{total variation} distance is given by
    \[
        \norm{\mu-\nu}_{\msf{TV}} := \sup_{B \in \mc B(\R^d)} \abs{\mu(B) - \nu(B)}\,,
    \]
    where $\mc B(\R^d)$ is the collection of all Borel measurable subsets of $\R^d$. The \emph{$q$-R\'enyi divergence} is defined as
    \[
        \eu R_q(\mu \mmid \nu) := \frac{1}{q-1} \log \int \bigl(\frac{\D \mu}{\D \nu}\bigr)^q\, \D \nu\,,
    \]
    if $\mu \ll \nu$, and $ \eu R_q(\mu \mmid \nu) := \infty$ otherwise. In the limit $q \to 1$, it converges to the $\KL$ divergence,
    \[
        \KL(\mu \mmid \nu) := \int \log \frac{\D \mu}{\D \nu} \, \D \mu\,,
    \]
    if $\mu \ll \nu$, and again $\KL(\mu \mmid \nu) := \infty$ otherwise. The $\chi^2$-divergence is defined as $\chi^2(\mu \mmid \pi) := \exp(\eu R_2(\mu \mmid \nu)) - 1$. Finally, the limit $\lim_{q \to \infty} \eu R_q(\mu \mmid \nu)$ can be written as
    \[
        \eu R_\infty(\mu \mmid \nu) := \esssup_{\nu} \log \frac{\D \mu}{\D \nu}\,.
    \]
\end{defn}

\begin{defn}[Warmness]
    For $\mu \ll \nu$, we denote the warmness $M$ of $\mu$ with respect to $\nu$ as 
    \[
        M := \esssup_\nu \frac{\D \mu}{\D \nu} = \exp \bigl(\eu R_\infty(\mu \mmid \nu)\bigr)\,.
    \]
    Alternatively, if the above holds, then we also say that $\mu$ is an $M$-warm start for $\nu$.
\end{defn}

\begin{defn}[Log-Sobolev inequality]
    A probability measure $\nu$ satisfies a \emph{log-Sobolev inequality} ($\msf{LSI}$) with parameter $C_{\msf{LSI}}(\nu)$ if for all smooth functions $f: \R^d \to \R$,
    \begin{equation}\tag{LSI}\label{eq:lsi}
        \Ent_\nu(f^2) \leq 2 C_{\msf{LSI}}(\nu)\, \E_\nu[\norm{\nabla f}^2]\,,
    \end{equation}
    with $\Ent_\nu(f^2) := \E_\nu[f^2 \log f^2] - \E_\nu[f^2] \log \E_\nu[f^2]$.
\end{defn}

\begin{defn}[Poincar\'e inequality]
    A probability measure $\nu$ satisfies a \emph{Poincar\'e inequality} ($\msf{PI}$) with parameter $C_{\msf{PI}}(\nu)$ if for all smooth functions $f: \R^d \to \R$,
    \begin{equation}\tag{PI}\label{eq:pi}
        \Var_\nu f \leq C_{\msf{PI}}(\nu)\, \E_\nu[\norm{\nabla f}^2]\,,
    \end{equation}
    with $\Var_\nu f := \E_\nu[(f-\E_\nu f)^2]$.
\end{defn}

\begin{lem}\label{eq:isoperimetry-dist}
    Let $\mc K\subset \Rd$ be a convex body with diameter $D$. Then, if $\pi \propto \ind_{\mc K}$ is the uniform distribution on $\mc K$,
    \[  
        C_{\msf{LSI}}(\pi) \lesssim D^2 \qquad \text{and} \qquad C_{\msf{PI}}(\pi) \lesssim \norm{\Sigma} \log d\,,
    \]
    where $\Sigma = \E_{X \sim \pi}[(X- \E_{\pi} X)(X- \E_{\pi} X)^\T]$ is the covariance of $\pi$. For a Gaussian $\pi_{\sigma^2} = \mc N(0, \sigma^2 I_d)|_{\mc K}$, we have
    \[
        C_{\msf{PI}}(\pi_{\sigma^2})\leq \clsi(\pi_{\sigma^2}) \leq \sigma^2\,.
    \]
\end{lem}

\begin{defn}[Markov kernel]
    Let $(\Omega, \mc F)$ be a measurable space. A \emph{Markov kernel} $P: \Omega \times \mc F \to [0, 1]$ satisfies
    \begin{enumerate}
        \item for each $x \in \Omega$, the map $P(\cdot | x):=P(x, \cdot)$ from $\mc F$ to $[0,1]$ is a probability measure on $(\Omega, \mc F)$.
        \item for each $E \in \mc F$, the map $P(\cdot, E)$ from $\Omega$ to $[0,1]$ is $\mc F$-measurable.
    \end{enumerate}
\end{defn}

Given a probability measure $\mu$ over $\Omega$ and function $f:\Omega\to\R$, a Markov kernel $P$ acts on $\mu$ and $f$ to yield objects $\mu P$ and $Pf$ defined by 
\begin{align*}
\mu P(\cdot) &:= \int_{\Omega}P(\cdot|x)\,\mu(\D x)\,,\\
Pf(x) &:= \E_{Y\sim P(\cdot|x)}[f(Y)]=\int_\Omega f(y)\, P(\D y|x)\,.
\end{align*}

Instead, it is natural to study the contraction coefficient in $L^\infty(\pi)$, defined by
\[
\norm P_{L^{\infty}\to L^{\infty}}:=\sup_{0\neq f\in L^\infty_0}\frac{\norm{Pf}_{L^\infty}}{\norm f_{L^\infty}}\,,
\]
where $\norm{f}_{L^\infty} := \norm{f}_{L^\infty(\pi)} = \esssup_{\pi}\abs{f}$ and $L^{\infty}_0:=\{f:\esssup_{\pi}\abs{f}<\infty, \E_\pi f=0\}$.

\begin{thm}\label{thm:boosting}
Consider a Markov chain with kernel $P$, initial distribution $\mu$ and stationary distribution $\pi$. Then,
\[
\bnorm{\frac{\D\mu P^{n}}{\D\pi}-1}_{L^{\infty}}\leq\bnorm{\frac{\D\mu}{\D\pi}-1}_{L^{\infty}}\cdot2\esssup_{x}\norm{P^{n}(\cdot|x)-\pi}_{\tv}\,
\]
In particular, $\eu R_\infty(\mu P^n \mmid \pi) \leq \bnorm{\frac{\D\mu}{\D\pi}-1}_{L^{\infty}}\cdot2\esssup_{x}\norm{P^{n}(\cdot|x)-\pi}_{\tv}$.
\end{thm}

\begin{algorithm}
\hspace*{\algorithmicindent} \textbf{Input:} initial point
$x_0 \sim \mu_{0}$, convex body $\mc K\subset\R^{d}$, iterations $T$, threshold $N$, and $h>0$.

\hspace*{\algorithmicindent} \textbf{Output:} $x_{T+1}$.

\begin{algorithmic}[1] \caption{$\msf{Prox\text{-}Gaussian}$} 
\label{alg:prox-gaussian}
\FOR{$i=0,\dotsc,T$}

\STATE Sample $y_{i+1}\sim
\mc N(x_{i},hI_{d})$.\label{line:forward-gsn}

\STATE 
Repeat: Sample $x_{i+1}\sim\mc N\bpar{\frac{1}{1+h\sigma^{-2}}y,\frac{h}{1+h\sigma^{-2}}I_{d}}\cdot\ind_{\mc K}$ until $x_{i+1}\in\mc K$ or \#attempts$_{i}$ $\geq N$ (declare \textbf{Failure}).\label{line:backward-gsn} 
\ENDFOR
\end{algorithmic}
\end{algorithm}

\begin{lem}\label{lem:contraction-prox-gauss}
    Let $\mu^X_k$ be the law of the $k$-th output of the $\ps$ with initial distribution $\mu_0^X$ and target $\pi^X = \mc N(0,\sigma^2 I_d)|_{\K}$.
    Then, for any $q \geq 1$,
    \[
    \eu R_q(\mu_k^X\mmid \pi^X) \leq \frac{\eu R_q(\mu_0^X \mmid \pi^X)}{(1+h\sigma^{-2})^{2k/q}}\,.
    \]
\end{lem}

\begin{lem}\label{lem:num-membership-queries}
Let $\K$ be a convex body in $\Rd$, and $\mu$ an initial distribution $M$-warm with respect to $\pi^{X}$. For any given $n\in\mathbb{N}$ and $\eta\in(0,1)$, set $Z=\frac{9nM}{\eta}(\geq9)$, $h=\sigma^{2}\frac{\log\log Z}{\log Z}(d^{-1}\wedge(d^{2}\sigma^{2}-\frac{\log\log Z}{2\log Z})^{-1})$ and $N=Z(\log Z)^{4}=\Otilde(\frac{nM}{\eta})$. Then, the failure probability of one iteration is at most $\eta/n$. Moreover, the expected number of membership queries needed per iteration is $\O\bpar{M(\log\frac{nM}{\eta})^{4}}$.
\end{lem}
