ground_truth_solution:
We start by proving the following 2 auxiliary statements:

\begin{lem}\label{lem:prox-gauss-anystart}
For any given $\varepsilon\in(0,1)$, the $\ps$ for a truncated Gaussian $\pi^X$ with variance $h$ and any feasible start $x_{0}\in\mc K$ achieves $\eu R_{\infty}(\mu_{n}^{X}\mmid\pi^{X})\leq \veps$ for $n=\Otilde(h^{-1}\sigma^{2}\log\frac{d+h^{-1}D^{2}}{\veps})$ iterations.
\end{lem}
\begin{proof}
We bound the warmness of $\mu_{1}^{X}$ towards $\pi^{X}$ when $\mu_{0}^{X}=\delta_{x_{0}}$.
One can readily check that  

\[
\mu_{1}^{X}(x)=\ind_{\mc K}(x)\cdot\int\frac{\exp\bpar{-\frac{1+h\sigma^{-2}}{2h}\bnorm{x-\frac{1}{1+h\sigma^{-2}}y}^{2}}\exp\bpar{-\frac{1}{2h}\norm{y-x_{0}}^{2}}}{(2\pi h)^{d/2}\int_{\mc K}\exp\bpar{-\frac{1+h\sigma^{-2}}{2h}\bnorm{z-\frac{1}{1+h\sigma^{-2}}y}^{2}}\,\D z}\,\D y\,,
\]
and we should compare this with 
\[
\pi^X(x) = \frac{\exp\bpar{-\frac{1}{2\sigma^{2}}\norm x^{2}}\cdot\ind_{\mc K}(x)}{\int_{\mc K}\exp\bpar{-\frac{1}{2\sigma^{2}}\norm z^{2}}\,\D z}\,.
\]

For $D=\text{diam}(\mc K)$,
\begin{align*}
\exp\Bpar{-\frac{1+h\sigma^{-2}}{2h}\bnorm{z-\frac{1}{1+h\sigma^{-2}}y}^{2}} & =\exp\bpar{-\frac{1}{2h}\norm z^{2}-\frac{1}{2\sigma^{2}}\norm z^{2}-\frac{1}{2h(1+h\sigma^{-2})}\norm y^{2}+\frac{z^{\T}y}{h}}\\
 & \geq\exp\bpar{-\frac{D^{2}}{2h}}\cdot\exp\bpar{-\frac{1}{2\sigma^{2}}\norm z^{2}-\frac{1}{2h(1+h\sigma^{-2})}\norm y^{2}+\frac{z^{\T}y}{h}}\,.
\end{align*}
As $|z^{\T}y|\leq\half(2\norm z^{2}+\half\norm y^{2})$ due to Young's inequality, 
\begin{align*}
 & \exp\bpar{-\frac{D^{2}}{2h}}\cdot\exp\bpar{-\frac{1}{2\sigma^{2}}\norm z^{2}-\frac{1}{2h(1+h\sigma^{-2})}\norm y^{2}+\frac{z^{\T}y}{h}}\\
\geq & \exp\bpar{-\frac{D^{2}}{2h}}\cdot\exp\bpar{-\frac{1}{2\sigma^{2}}\norm z^{2}-\frac{1}{2h(1+h\sigma^{-2})}\norm y^{2}-\frac{\norm z^{2}}{h}-\frac{\norm y^{2}}{4h}}\\
\geq & \exp\bpar{-\frac{3D^{2}}{2h}}\cdot\exp\bpar{-\frac{1}{2\sigma^{2}}\norm z^{2}-\frac{1}{2h(1+h\sigma^{-2})}\norm y^{2}-\frac{\norm y^{2}}{4h}}\,.
\end{align*}
Hence, 
\begin{align*}
 & \int\frac{\exp\bpar{-\frac{1+h\sigma^{-2}}{2h}\bnorm{x-\frac{1}{1+h\sigma^{-2}}y}^{2}}\exp\bpar{-\frac{1}{2h}\norm{y-x_{0}}^{2}}}{(2\pi h)^{d/2}\int_{\mc K}\exp\bpar{-\frac{1+h\sigma^{-2}}{2h}\bnorm{z-\frac{1}{1+h\sigma^{-2}}y}^{2}}\,\D z}\,\D y\\
 \leq & \underbrace{\frac{\exp\bpar{\frac{3D^{2}}{2h}}}{(2\pi h)^{d/2}}\int\frac{\exp\bpar{-\frac{1+h\sigma^{-2}}{2h}\bnorm{x-\frac{1}{1+h\sigma^{-2}}y}^{2}}\exp\bpar{-\frac{1}{2h}\norm{y-x_{0}}^{2}}\exp\bpar{\frac{1}{2h(1+h\sigma^{-2})}\norm y^{2}+\frac{\norm y^{2}}{4h}}}{\int_{\mc K}\exp\bpar{-\frac{1}{2\sigma^{2}}\norm z^{2}}\,\D z}\,\D y}_{\eqqcolon (\#)}\,.
\end{align*}
The numerator of the integrand can be bounded as follows:
\begin{align*}
    &\exp\bpar{-\frac{1+h\sigma^{-2}}{2h}\bnorm{x-\frac{1}{1+h\sigma^{-2}}y}^{2}}\exp\bpar{-\frac{1}{2h}\norm{y-x_{0}}^{2}}\exp\bpar{\frac{1}{2h(1+h\sigma^{-2})}\norm y^{2}+\frac{\norm y^{2}}{4h}}\\
    =& \exp\Bpar{-\frac{1}{4h}\norm{y-2(x_{0}+x)}^{2}-\frac{1}{2h}\bpar{\norm{x_{0}}^{2}+\norm x^{2}+\frac{h}{\sigma^{2}}\norm x^{2}-2\norm{x_{0}+x}^{2}}}\\
    \leq& \exp\bpar{\frac{D^2}{h}} \exp\bpar{-\frac{1}{4h}\norm{y-2(x_0+x)}^2-\frac{1}{2\sigma^2}\norm{x}^2}\,.
\end{align*}
Putting this bound back to the integral above,
\begin{align*}
    (\#) &\leq \frac{\exp\bpar{\frac{5D^{2}}{2h}}}{(2\pi h)^{d/2}}\frac{\int\exp\bpar{-\frac{1}{4h}\norm{y-2(x_{0}+x)}^{2}}\,\D y}{\int_{\mc K}\exp\bpar{-\frac{1}{2\sigma^{2}}\norm z^{2}}\,\D z}\cdot\exp\bpar{-\frac{1}{2\sigma^{2}}\norm x^{2}}\\
    &= 2^{d/2}\exp\Bpar{\frac{5D^{2}}{h}}\frac{\exp\bpar{-\frac{1}{2\sigma^{2}}\norm x^{2}}}{\int_{\mc K}\exp\bpar{-\frac{1}{2\sigma^{2}}\norm z^{2}}\,\D z} \leq 2^{d/2}\exp\Bpar{\frac{5D^{2}}{h}}\,.
\end{align*}
Therefore, the ratio can be bounded by 
\begin{align*}
 & \frac{\int_{\mc K}\exp\bpar{-\frac{1}{2\sigma^{2}}\norm z^{2}}\,\D z}{\exp\bpar{-\frac{1}{2\sigma^{2}}\norm x^{2}}} \int\frac{\exp\bpar{-\frac{1+h\sigma^{-2}}{2h}\bnorm{x-\frac{1}{1+h\sigma^{-2}}y}^{2}}\exp\bpar{-\frac{1}{2h}\norm{y-x_{0}}^{2}}}{(2\pi h)^{d/2}\int_{\mc K}\exp\bpar{-\frac{1+h\sigma^{-2}}{2h}\bnorm{z-\frac{1}{1+h\sigma^{-2}}y}^{2}}\,\D z}\,\D y\leq2^{d/2}\exp\Bpar{\frac{5D^{2}}{h}}\,,
\end{align*}
so $M=\esssup\frac{\mu_{1}^{X}}{\pi^{X}}\leq2^{d/2}\exp(5h^{-1}D^{2})$, and $\eu R_{q}(\mu_{1}^{X}\mmid\pi^{X})\lesssim\frac{q}{q-1}\log M\leq\frac{q}{q-1}\bpar{d+h^{-1}D^{2}}$. By Lemma~\ref{lem:contraction-prox-gauss}, one can achieve $\eu R_q(\mu_n^X\mmid \pi^X) \leq \veps$ for $n = \Otilde(qh^{-1}\sigma^2 \log\frac{d+h^{-1}D^2}{\veps})$.

Using $2\norm{\cdot}_{\tv}^{2}\leq\KL=\lim_{q\downarrow1}\eu R_{q}$ and $\clsi(\pi^X)\leq \sigma^2$, one can achieve that after $n\gtrsim h^{-1}\sigma^{2}\log\frac{M(d+h^{-1}D^{2})}{\veps}$ iterations,
\[
\sup_{x\in\mc K}\norm{\mu^X_n-\pi^X}_{\tv}\leq\frac{\veps}{M}\,.
\]
By Theorem~\ref{thm:boosting} with $\bnorm{\frac{\D\mu^X_1}{\D\pi^X}-1}_{L_{\infty}}\leq M$, we have $\bnorm{\frac{\D\mu^X_n}{\D\pi^X}-1}_{L_{\infty}}\leq\veps$ and $\eu R_{\infty}(\mu^X_n \mmid\pi)\leq\veps$.
\end{proof}

\begin{prop}\label{prop:ps-gauss-Rq}
For any $\eta,\varepsilon \in (0,1)$, $q\geq 1$, $n\in \mathbb{N}$ defined below and convex body $\K$ given by a well-defined membership oracle, the $\ps$ (Algorithm~\ref{alg:prox-gaussian}) with $h = \sigma^{2}(\frac{1}{d}\wedge\frac{1}{d^{2}\sigma^{2}-1})(\log\frac{9nM}{\eta})^{-1}$, $N = \Otilde(\frac{nM}{\eta})$, and initial distribution $\mu_0^X$ which is $M$-warm with respect to $\pi^X = \mc N(0, \sigma^2 I_d)|_{\K}$ achieves  $\eu R_q(\mu^X_n \mmid \pi^X)\leq \veps$ after $n = \Otilde\bigl(q(d\vee d^2\sigma^2) \log\frac{M}{\eta \veps}\bigr)$ iterations, where $\mu_n^X$ is the law of the $n$-the iterate. 
With probability $1-\eta$, the algorithm iterates $n$ times without failure, using $\Otilde\bpar{qM(d\vee d^{2}\sigma^{2})(\log\nicefrac{1}{\eta\veps})^5}$ expected number of membership queries in total. In particular, the query complexity is $\Otilde(qMd^{2}\sigma^{2}(\log\nicefrac{1}{\eta\veps})^5)$ when $d^{-1}\lesssim \sigma^2$.
\end{prop}
\begin{proof}
By Lemma~\ref{lem:contraction-prox-gauss}, the $\ps$ should iterate
$\O\bpar{q\sigma^{2}h^{-1}\log\frac{\log M}{\veps}}$ times to achieve $\veps$-distance in $\eu R_{q}$. To ensure that the query complexity is bounded, we choose
\[
h=\sigma^{2}\frac{\log\log Z}{\log Z}\bpar{\frac{1}{d}\wedge\frac{1}{d^{2}\sigma^{2}-1}}\quad \text{and}\quad N = \frac{9nM}{\eta} \bpar{\log \frac{9nM}{\eta}}^4\,.
\]
By Lemma~\ref{lem:num-membership-queries}, we need the following total number of membership queries in expectation:
\[
\Otilde\Bpar{qM(d\vee d^{2}\sigma^{2})\bpar{\log\frac{1}{\eta\veps}}^5}\,.
\]
Hence, if $d^{-1}\lesssim\sigma^{2}$, then the query complexity is simply $\Otilde(qMd^{2}\sigma^{2}\log^5\nicefrac{1}{\eta\veps})$.    
\end{proof}

With the above in mind, we are now ready to prove the main statement:

\begin{proof}
 By Lemma~\ref{lem:prox-gauss-anystart}, the $\ps$ should iterate $n=\Otilde\bigl((d\vee d^2\sigma^2)(\log\frac{MD}{\eta\veps})^2\bigr)$ times to output a sample whose law is $\veps$-close to $\pi^X$ in $\eu R_\infty$. 
 As argued in Proposition~\ref{prop:ps-gauss-Rq}, we can conclude that throughout $n$ outer iterations, the failure probability of the $\ps$ is at most $\eta$ by the union bound, and the total expected number of queries is $\Otilde\bigl(M(d\vee d^2\sigma^2)(\log\frac{D}{\eta\veps})^6\bigr)$.
\end{proof}
